query Positions($owner: String!) {
  positions(where: { owner: $owner, liquidity_gt: "0" }) {
    id
    owner
    liquidity
    depositedToken0
    depositedToken1
    withdrawnToken0
    withdrawnToken1
    tickLower
    tickUpper
    token0 {
      symbol
    }
    token1 {
      symbol
    }
    pool {
      id
      tick
      token0 {
        symbol
      }
      token1 {
        symbol
      }
    }
  }
}
